function renderLayers(){const root=$('#layersTree');const current=page();if(!root||!current)return;root.replaceChildren();const walk=(id,depth=0)=>{const node=getNode(current,id);if(!node)return;const row=document.createElement('button');row.type='button';row.dataset.nodeId=id;row.draggable=node.id!==current.rootId&&!node.locked;row.className=`layer-row ${state.selection.primaryId===id?'active':''} ${node.locked?'locked':''}`;row.style.paddingLeft=`${8+depth*14}px`;row.innerHTML=`<span class="layer-caret">${node.children?.length?'â–¸':'Â·'}</span><strong>${node.name||node.type}</strong><small>${node.type}</small><span class="layer-drag-handle" role="button" tabindex="-1" aria-label="Elem mozgatÃ¡sa">â ¿</span>${node.locked?'<span class="layer-lock" title="ZÃ¡rolt elem" aria-label="ZÃ¡rolt elem">ğŸ”</span>':''}`;const handle=row.querySelector('.layer-drag-handle');row.ondragstart=e=>handleLayerDragStart(id,e,row);row.ondragover=e=>handleLayerDragOver(id,e,row);row.ondrop=e=>handleLayerDrop(id,e,row);row.ondragend=()=>clearHierarchyDrag();handle?.addEventListener('pointerdown',e=>handleMobileLayerDragStart(id,e,handle));handle?.addEventListener('pointermove',e=>handleMobileLayerDragMove(e));handle?.addEventListener('pointerup',e=>handleMobileLayerDragEnd(e));handle?.addEventListener('pointercancel',e=>clearMobileHierarchyDrag());row.onpointerdown=e=>{if(e.pointerType==='touch'){e.stopPropagation();handleMobilePointerDown(id,e)}};row.onpointermove=e=>{if(e.pointerType==='touch')handleMobilePointerMove(e)};row.onpointerup=e=>{if(e.pointerType==='touch'){e.stopPropagation();handleMobilePointerUp(id,e)}};row.onpointercancel=e=>{if(e.pointerType==='touch')handleMobilePointerCancel(e)};row.onclick=e=>{e.stopPropagation();if(mobileTouch.active&&mobileTouch.suppressClick){mobileTouch.suppressClick=false;return}selectNodeInteraction(id,e)};root.append(row);for(const child of node.children||[])walk(child,depth+1)};walk(current.rootId)}
function syncPublishControls(){const current=page();const meta=current&&pages.find(x=>x.id===current.id);const published=Boolean(meta?.isPublished);const dirty=Boolean(state?.persistence?.dirty);const draftAhead=published&&Number(meta?.publishedRevisionVersion??0)<Number(meta?.revision??0);const publishLabel=published?(dirty||draftAhead?'ÃšjrapublikÃ¡lÃ¡s':'PublikÃ¡lva'):'PublikÃ¡lÃ¡s';const publishDisabled=!current||(!dirty&&!draftAhead&&published);const publish=$('#publish'),unpublish=$('#unpublish'),mobilePublish=$('#mobilePublish'),mobileUnpublish=$('#mobileUnpublish');if(publish){publish.textContent=publishLabel;publish.disabled=publishDisabled}if(unpublish)unpublish.hidden=!published;if(mobilePublish){mobilePublish.textContent=publishLabel;mobilePublish.disabled=publishDisabled}if(mobileUnpublish)mobileUnpublish.hidden=!published}
function renderRevisionPanel(){const root=$('#revisionList');if(!root)return;root.replaceChildren();if(!revisionHistory.length){const empty=document.createElement('div');empty.className='revision-empty';empty.textContent='Nincs korÃ¡bbi revision.';root.append(empty);return}for(const rev of revisionHistory){const row=document.createElement('div');row.className='revision-row';const info=document.createElement('div');info.className='revision-info';const title=document.createElement('strong');title.textContent=`v${rev.version}`;const note=document.createElement('span');note.textContent=rev.note||'Editor mentÃ©s';const date=document.createElement('small');date.textContent=rev.created_at?new Date(rev.created_at).toLocaleString('hu-HU'):'â€”';info.append(title,note,date);const button=document.createElement('button');button.type='button';button.className='revision-restore';button.textContent='VisszaÃ¡llÃ­tÃ¡s';button.disabled=Number(rev.version)===Number(page()?.revision||0);button.title=button.disabled?'Ez az aktuÃ¡lis revision':'Ezt a revisiont Ã¡llÃ­tja vissza Ãºj revisionkÃ©nt';button.onclick=()=>rollbackToRevision(Number(rev.version));row.append(info,button);root.append(row)}}
