async function loadPages(){setStatus('Oldalak betÃ¶ltÃ©seâ€¦');const data=await api('/api/admin/pages');if(!Array.isArray(data.data))throw new Error('HibÃ¡s oldallistÃ¡zÃ³ vÃ¡lasz');pages=data.data;renderPageList();const initialId=initialPageId(requestedPageId(),pages);if(!state&&initialId)await loadPage(initialId);else if(state){renderPageList();render();setStatus(state.persistence.dirty?'Nem mentett mÃ³dosÃ­tÃ¡s':'Mentve')}else{rememberPageId(null);setStatus('Nincs oldal')}}
async function loadPage(id){setStatus('Oldal betÃ¶ltÃ©seâ€¦');const meta=pages.find(x=>x.id===id);if(!meta)throw new Error('Az oldal nem talÃ¡lhatÃ³.');const data=await api('/api/admin/editor?pageId='+encodeURIComponent(id));const document=data?.data?.page?.document||meta.content;const revisions=Array.isArray(data?.data?.revisions)?data.data.revisions:[];if(!canonical(document,id))throw new Error(`Az oldal (${meta.title||meta.slug}) nem canonical Editor v2 dokumentum.`);const rawRevision=revisions.length?Number(revisions[0]?.version):0;if(!Number.isInteger(rawRevision)||rawRevision<0)throw new Error('HibÃ¡s revision-vÃ¡lasz: a szerver revision-szÃ¡ma nem Ã©rvÃ©nyes.');revisionHistory=revisions;const latestRevision=rawRevision;meta.revision=latestRevision;meta.publishedRevisionId=data?.data?.page?.publishedRevisionId??meta.publishedRevisionId??null;meta.publishedRevisionVersion=meta.publishedRevisionId?Number(revisions.find(rev=>rev.id===meta.publishedRevisionId)?.version||0):0;document.revision=latestRevision;document.pages[id].revision=latestRevision;state=createEditorState(document);markSaved(state,latestRevision);rememberPageId(id);renderPageList();render();setStatus('Mentve')}
