async function createNew(){const title=prompt('Ãšj oldal neve','Ãšj oldal');if(!title)return;const slug=prompt('Slug',title.toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''));if(!slug)return;const p=createPage({name:title,slug});await api('/api/admin/pages',{method:'POST',body:JSON.stringify({id:p.id,title,slug,description:'',document:createDocument(p)})});await loadPages();await loadPage(p.id)}
async function save(publish=false){if(state?.persistence?.saving){setStatus('MentÃ©s folyamatbanâ€¦');return;}const current=page();if(!current)return;const meta=pages.find(x=>x.id===current.id);if(!meta)return;const stateAtStart=state;const pageId=current.id;const submittedDocument=structuredClone(stateAtStart.document);const submittedJson=JSON.stringify(submittedDocument);const expectedVersion=Number(meta.revision??stateAtStart.document.revision??0);setStatus(publish?'PublikÃ¡lÃ¡sâ€¦':'MentÃ©sâ€¦');stateAtStart.persistence.saving=true;try{const result=await api(`/api/admin/editor?pageId=${encodeURIComponent(pageId)}`,{method:'POST',body:JSON.stringify({pageId,document:submittedDocument,publish,expectedVersion,note:publish?'Editor v2 publikÃ¡lÃ¡s':'Editor v2 mentÃ©s'})});const version=Number(result?.data?.version);if(result?.data?.pageId!==pageId||!Number.isInteger(version)||version<1)throw new Error('A mentÃ©s vÃ¡lasza hiÃ¡nyos vagy hibÃ¡s revision-adatot tartalmaz; a helyi mÃ³dosÃ­tÃ¡sokat nem jelÃ¶ltÃ¼k mentettnek.');const unchanged=state===stateAtStart&&JSON.stringify(stateAtStart.document)===submittedJson;stateAtStart.document.revision=version;if(stateAtStart.document.pages?.[pageId])stateAtStart.document.pages[pageId].revision=version;meta.revision=version;if(unchanged){markSaved(stateAtStart,version)}else{stateAtStart.persistence.saving=false;stateAtStart.persistence.dirty=true;stateAtStart.persistence.error=null;stateAtStart.persistence.lastSavedRevision=version}stateAtStart.persistence.conflict=null;const panel=$('#revisionConflict');if(panel&&state===stateAtStart)panel.hidden=true;const i=pages.findIndex(x=>x.id===pageId);if(i>=0){const previous=pages[i];pages[i]={...previous,content:submittedDocument,isPublished:Boolean(previous.isPublished),publishedRevisionId:publish?result.data.revisionId:previous.publishedRevisionId,publishedRevisionVersion:publish?version:Number(previous.publishedRevisionVersion??0),revision:version};}renderPageList();if(state===stateAtStart){render();setStatus(unchanged?(publish?'PublikÃ¡lva':(pages.find(x=>x.id===pageId)?.isPublished?'Mentve â€” a nyilvÃ¡nos oldal vÃ¡ltozatlan':'Mentve')):'A mentett verziÃ³ elkÃ©szÃ¼lt; tovÃ¡bbi helyi mÃ³dosÃ­tÃ¡sok mÃ©g nincsenek mentve')}return result}catch(e){stateAtStart.persistence.saving=false;stateAtStart.persistence.dirty=true;stateAtStart.persistence.error=e instanceof Error?e.message:String(e);if(state===stateAtStart&&e?.status===409&&e?.code==='REVISION_CONFLICT'){showRevisionConflict(e,pageId);return}if(state===stateAtStart){setStatus('MentÃ©si hiba');alert(stateAtStart.persistence.error)}return}}
